CREATE TABLE IF NOT EXISTS players (id TEXT PRIMARY KEY, name TEXT NOT NULL, token_hash TEXT NOT NULL, division INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS reports (player_id TEXT NOT NULL, week TEXT NOT NULL, score REAL NOT NULL, city INTEGER NOT NULL, stars INTEGER NOT NULL, city_earned REAL NOT NULL, levels TEXT NOT NULL, at INTEGER NOT NULL, PRIMARY KEY (player_id, week));
CREATE TABLE IF NOT EXISTS groups (week TEXT NOT NULL, player_id TEXT NOT NULL, division INTEGER NOT NULL, group_no INTEGER NOT NULL, PRIMARY KEY (week, player_id));
CREATE INDEX IF NOT EXISTS groups_by_group ON groups (week, division, group_no);
CREATE TABLE IF NOT EXISTS leagues (code TEXT PRIMARY KEY, name TEXT NOT NULL, owner TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS league_members (code TEXT NOT NULL, player_id TEXT NOT NULL, joined_at INTEGER NOT NULL, PRIMARY KEY (code, player_id));
CREATE INDEX IF NOT EXISTS members_by_player ON league_members (player_id);
CREATE TABLE IF NOT EXISTS rollovers (week TEXT PRIMARY KEY, at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS rejects (player_id TEXT NOT NULL, week TEXT NOT NULL, reason TEXT NOT NULL, at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS attest_keys (key_id TEXT PRIMARY KEY, player_id TEXT NOT NULL, public_key TEXT NOT NULL, environment TEXT NOT NULL, counter INTEGER NOT NULL, at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS attest_keys_by_player ON attest_keys (player_id);
CREATE TABLE IF NOT EXISTS attest_challenges (player_id TEXT PRIMARY KEY, challenge TEXT NOT NULL, expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS tokens (token_hash TEXT PRIMARY KEY, player_id TEXT NOT NULL, platform TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS tokens_by_player ON tokens (player_id);
CREATE TABLE IF NOT EXISTS saves (player_id TEXT PRIMARY KEY, version INTEGER NOT NULL, state TEXT NOT NULL, cursor INTEGER NOT NULL, batch TEXT, at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS profiles (player_id TEXT PRIMARY KEY, platform TEXT NOT NULL, stars INTEGER NOT NULL, city INTEGER NOT NULL, at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS profiles_by_stars ON profiles (stars);
CREATE TABLE IF NOT EXISTS links (code TEXT PRIMARY KEY, player_id TEXT NOT NULL, expires_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS links_by_player ON links (player_id);
CREATE TABLE IF NOT EXISTS seed_verified (player_id TEXT NOT NULL, week TEXT NOT NULL, id TEXT NOT NULL UNIQUE, company TEXT NOT NULL, ceo TEXT, score REAL NOT NULL, curve TEXT NOT NULL, code TEXT NOT NULL, code_key TEXT NOT NULL, idle INTEGER NOT NULL DEFAULT 0, at INTEGER NOT NULL, PRIMARY KEY (player_id, week));
CREATE INDEX IF NOT EXISTS seed_verified_by_week ON seed_verified (week, score DESC, at);
CREATE INDEX IF NOT EXISTS seed_verified_by_code ON seed_verified (code_key);
CREATE TABLE IF NOT EXISTS seed_gaps (player_id TEXT PRIMARY KEY, at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS seed_limits (key TEXT PRIMARY KEY, hour INTEGER NOT NULL, count INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS seed_leagues (code TEXT PRIMARY KEY, name TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS seed_league_members (code TEXT NOT NULL, player_id TEXT NOT NULL, joined_at INTEGER NOT NULL, PRIMARY KEY (code, player_id));
CREATE INDEX IF NOT EXISTS seed_league_members_by_player ON seed_league_members (player_id);
